// Version A: unified hierarchy where each subtype implements its own behavior
abstract class Document { abstract process(): void }
class Invoice extends Document { process() { /* invoice processing */ } }
class Receipt extends Document { process() { /* receipt processing */ } }

// Version B: separate type and processor hierarchies requiring matched subclasses
abstract class DocumentType {}
class InvoiceType extends DocumentType {}
class ReceiptType extends DocumentType {}
abstract class Processor { abstract handle(t: DocumentType): void }
class InvoiceProcessor extends Processor { handle(t: InvoiceType) { /* ... */ } }
class ReceiptProcessor extends Processor { handle(t: ReceiptType) { /* ... */ } }
